package mz.bam.seeky.android;
import android.content.*;import android.widget.*;import org.json.*;

/** Per-book voice and ambient choices. Settings files contain no account credentials. */
final class ReadingProfiles {
    final ReaderActivity a;final String key;boolean applied;
    ReadingProfiles(ReaderActivity a){this.a=a;key=BookSettings.key(a,a.uri,a.getIntent().getLongExtra("study_material",0));}
    static JSONObject capture(Context c)throws JSONException{android.content.SharedPreferences voice=c.getSharedPreferences("seeky",0),background=c.getSharedPreferences("reading_background",0);return new JSONObject().put("engine",voice.getString("speech_engine","com.google.android.tts")).put("voice",voice.getString("speech_voice","")).put("language",voice.getString("speech_language","pt")).put("online",voice.getBoolean("speech_online",false)).put("rate",voice.getFloat("speech_rate",1f)).put("pause_ms",voice.getInt("speech_title_pause_ms",2000)).put("background_path",background.getString("path","")).put("background_name",background.getString("name","")).put("background_enabled",background.getBoolean("enabled",false)).put("background_volume",background.getInt("volume",15));}
    static void apply(Context c,JSONObject value){c.getSharedPreferences("seeky",0).edit().putString("speech_engine",value.optString("engine","com.google.android.tts")).putString("speech_voice",value.optString("voice","")).putString("speech_language",value.optString("language","pt")).putBoolean("speech_online",value.optBoolean("online",false)).putFloat("speech_rate",(float)Math.max(.5,Math.min(2,value.optDouble("rate",1)))).putInt("speech_title_pause_ms",Math.max(500,Math.min(5000,value.optInt("pause_ms",2000)))).apply();String path=value.optString("background_path","");try{if(!path.isEmpty()&&!DiskWalker.inside(new java.io.File(c.getFilesDir(),"backgrounds").getCanonicalFile(),new java.io.File(path).getCanonicalFile()))path="";}catch(java.io.IOException e){path="";}c.getSharedPreferences("reading_background",0).edit().putString("path",path).putString("name",value.optString("background_name","Fundo")).putBoolean("enabled",!path.isEmpty()&&value.optBoolean("background_enabled",false)).putInt("volume",Math.max(0,Math.min(100,value.optInt("background_volume",15)))).apply();}
    void resume(){android.content.SharedPreferences tools=a.getSharedPreferences("reading_tools",0);if(applied&&tools.getString("active_book_profile","").equals(key))return;JSONObject profile=BookSettings.get(a,key).optJSONObject("profile");if(profile!=null)apply(a,profile);tools.edit().putString("active_book_profile",key).apply();applied=true;}
    void save(){if(!applied||!a.getSharedPreferences("reading_tools",0).getString("active_book_profile","").equals(key))return;try{JSONObject profile=capture(a);final android.content.Context app=a.getApplicationContext();a.worker.execute(()->{try{if(a.workspaceEpoch!=WorkspaceEpoch.value)return;BookSettings.update(app,key,value->value.put("profile",profile));}catch(Exception e){AppDiagnostics.record(app,"book-profile",e);}});}catch(Exception e){AppDiagnostics.record(a,"book-profile",e);}}
    void titles(){final int part=a.chrome.current();a.worker.execute(()->{try(SpeechDocument document=new SpeechDocument(a,a.uri,a.name,a.mime,()->a.dead)){String text=document.part(part);SpeechLayout.Plan plan=SpeechLayout.of(text,document.speechTitles(part));a.ui(()->{if(plan.titles.isEmpty()){PlusUi.toast(a,"Nenhum título detectado nesta parte.");return;}PagedPicker.show(a,"Títulos e pausas desta parte",(query,offset,limit)->{java.util.List<PagedPicker.Entry> all=new java.util.ArrayList<>();for(SpeechLayout.Title title:plan.titles){String label=SpeechLayout.clean(text.substring(title.start,title.end));if(!label.toLowerCase(java.util.Locale.ROOT).contains(query.toLowerCase(java.util.Locale.ROOT)))continue;int pause=a.getSharedPreferences("seeky",0).getInt("speech_title_pause_ms",2000);all.add(new PagedPicker.Entry(title.start+":"+title.end,label,AppLanguage.text(a,"Pausa após título")+" · "+(pause/1000f)+" s"));}return new PagedPicker.Page(new java.util.ArrayList<>(all.subList(Math.min(offset,all.size()),Math.min(offset+limit,all.size()))),all.size());},entry->{int end=Integer.parseInt(entry.id.split(":")[1]);String next=text.substring(end,Math.min(text.length(),end+700)).trim();new UiDialog.Builder(a).setTitle(entry.label).setMessage(entry.detail+"\n\n"+AppLanguage.text(a,"Texto seguinte")+":\n"+next).setPositiveButton("Fechar",null).show();});});}catch(Exception e){a.ui(()->PlusUi.error(a,e));}});}
    void show(){UiPanel p=new UiPanel(a,"Perfil deste livro",null,"speaker");p.note("A voz, idioma, velocidade e fundo ficam guardados para este livro.");p.action("speaker","Escolher voz e velocidade",null,false,()->a.chrome.speech.show(null,0));p.action("book","Rever títulos detectados",null,false,this::titles);p.action("clock","Pausa após títulos",null,false,()->{int value=a.getSharedPreferences("seeky",0).getInt("speech_title_pause_ms",2000);new UiDialog.Builder(a).setTitle("Pausa após títulos").setSingleChoiceItems(new String[]{"1 s","2 s","3 s","4 s","5 s"},Math.max(0,Math.min(4,value/1000-1)),(d,n)->{a.getSharedPreferences("seeky",0).edit().putInt("speech_title_pause_ms",(n+1)*1000).apply();d.dismiss();save();PlusUi.toast(a,"Pausa guardada para a próxima leitura.");}).setNegativeButton("Fechar",null).show();});p.action("check","Guardar opções actuais",null,false,()->{save();PlusUi.toast(a,"Perfil guardado para este livro.");});p.show();}
}
